package com.bank.dedup;

import java.util.*;
import java.util.logging.*;

public class DedupDemo {
    private static final Logger log = Logger.getLogger("Dedup");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> feed = List.of(
            new Employee(1L, "Rajesh"),
            new Employee(1L, "Rajesh"),      // exact duplicate
            new Employee(2L, "Priya"),
            new Employee(2L, "Priya Sharma") // same id, different name
        );
        EmployeeDedup service = new EmployeeDedup();

        List<Employee> exact = service.distinctExact(feed);
        log.info(() -> "After distinct() (exact): " + exact.size()); // 3

        List<Employee> byId = service.distinctById(feed);
        log.info(() -> "After distinct by id: " + byId.size());      // 2
        byId.forEach(e -> log.info(() -> "  id=" + e.id() + " name=" + e.name()));
    }
}

// ─── Would be in model/Employee.java ───
// record generates equals/hashCode over ALL components automatically
record Employee(Long id, String name) {}

// ─── Would be in service/EmployeeDedup.java ───
class EmployeeDedup {
    // distinct() uses equals/hashCode — removes EXACT duplicates only
    List<Employee> distinctExact(List<Employee> feed) {
        return feed.stream().distinct().collect(java.util.stream.Collectors.toList());
    }

    // dedupe by a KEY (id): Set.add returns true only for a new id → keep first
    List<Employee> distinctById(List<Employee> feed) {
        Set<Long> seen = java.util.concurrent.ConcurrentHashMap.newKeySet();
        return feed.stream()
            .filter(e -> seen.add(e.id()))   // stateful filter on the key
            .collect(java.util.stream.Collectors.toList());
    }
}
